#include <iostream>
using namespace std;

int main() {
    long long a, b;
    cin >> a >> b;

    if (b == 0) {
        cout << a << '\n';
        return 0;
    }

    long long num = a / b;
    long long total = a + num;

    while (b > 1 && num >= b) {
        num /= b;
        total += num;
    }

    cout << total << '\n';
    return 0;
}

