        cout << a << '\n';
        return 0;
    }

    num = a / b;
    set<long long> seen;

    while (b != 1 && b != 0 && !seen.count(b)) {
        seen.insert(b);
        b = num / b;
        num1 += b;
    }

    cout << num1 + num + a << '\n';
    return 0;
}

